     9→	"entire.io/cli/cmd/entire/cli/strategy"
    10→)
    11→
    12→// TaskHookInput represents the JSON input from PreToolUse[Task] hook
    13→type TaskHookInput struct {
    14→	SessionID      string          `json:"session_id"`
    15→	TranscriptPath string          `json:"transcript_path"`
    16→	ToolUseID      string          `json:"tool_use_id"`
    17→	ToolInput      json.RawMessage `json:"tool_input"`
    18→}
    19→
    20→// postTaskHookInputRaw is the raw JSON structure from PostToolUse[Task] hook
    21→type postTaskHookInputRaw struct {
    22→	SessionID      string          `json:"session_id"`
    23→	TranscriptPath string          `json:"transcript_path"`
    24→	ToolUseID      string          `json:"tool_use_id"`
    25→	ToolInput      json.RawMessage `json:"tool_input"`
    26→	ToolResponse   struct {
    27→		AgentID string `json:"agentId"`
    28→	} `json:"tool_response"`
    29→}
    30→
    31→// PostTaskHookInput represents the parsed input from PostToolUse[Task] hook
    32→type PostTaskHookInput struct {
    33→	TaskHookInput
    34→
    35→	AgentID   string          // Extracted from tool_response.agentId
    36→	ToolInput json.RawMessage // Raw tool input for reference
    37→}
    38→
    39→// parseTaskHookInput parses PreToolUse[Task] hook input from reader
    40→func parseTaskHookInput(r io.Reader) (*TaskHookInput, error) {
    41→	data, err := io.ReadAll(r)
    42→	if err != nil {
    43→		return nil, fmt.Errorf("failed to read input: %w", err)
    44→	}
    45→
    46→	if len(data) == 0 {
    47→		return nil, errors.New("empty input")
    48→	}
    49→
    50→	var input TaskHookInput
    51→	if err := json.Unmarshal(data, &input); err != nil {
    52→		return nil, fmt.Errorf("failed to parse JSON: %w", err)
    53→	}
    54→
    55→	return &input, nil
    56→}
    57→
    58→// parsePostTaskHookInput parses PostToolUse[Task] hook input from reader
    59→func parsePostTaskHookInput(r io.Reader) (*PostTaskHookInput, error) {
    60→	data, err := io.ReadAll(r)
    61→	if err != nil {
    62→		return nil, fmt.Errorf("failed to read input: %w", err)
    63→	}
    64→
    65→	if len(data) == 0 {
    66→		return nil, errors.New("empty input")
    67→	}
    68→
    69→	var raw postTaskHookInputRaw
    70→	if err := json.Unmarshal(data, &raw); err != nil {
    71→		return nil, fmt.Errorf("failed to parse JSON: %w", err)
    72→	}
    73→
    74→	return &PostTaskHookInput{
    75→		TaskHookInput: TaskHookInput{
    76→			SessionID:      raw.SessionID,
    77→			TranscriptPath: raw.TranscriptPath,
    78→			ToolUseID:      raw.ToolUseID,
    79→		},
    80→		AgentID:   raw.ToolResponse.AgentID,
    81→		ToolInput: raw.ToolInput,
    82→	}, nil
    83→}
    84→
    85→// logPreTaskHookContext logs the PreToolUse[Task] hook context to the writer
    86→func logPreTaskHookContext(w io.Writer, input *TaskHookInput) {
    87→	_, _ = fmt.Fprintln(w, "[entire] PreToolUse[Task] hook invoked")
    88→	_, _ = fmt.Fprintf(w, "  Session ID: %s\n", input.SessionID)
    89→	_, _ = fmt.Fprintf(w, "  Tool Use ID: %s\n", input.ToolUseID)
    90→	_, _ = fmt.Fprintf(w, "  Transcript: %s\n", input.TranscriptPath)
    91→}
