    93→// SubagentCheckpointHookInput represents the JSON input from PostToolUse hooks for
    94→// subagent checkpoint creation (TodoWrite, Edit, Write)
    95→type SubagentCheckpointHookInput struct {
    96→	SessionID      string          `json:"session_id"`
    97→	TranscriptPath string          `json:"transcript_path"`
    98→	ToolName       string          `json:"tool_name"`
    99→	ToolUseID      string          `json:"tool_use_id"`
