   769→// handleClaudeCodePreTask handles the PreToolUse[Task] hook
   770→func handleClaudeCodePreTask() error {
   771→	// Skip on default branch for strategies that don't allow it
   772→	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
   773→		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
   774→		return nil // Don't fail the hook, just skip
   775→	}
   776→
   777→	input, err := parseTaskHookInput(os.Stdin)
   778→	if err != nil {
   779→		return fmt.Errorf("failed to parse PreToolUse[Task] input: %w", err)
   780→	}
   781→
   782→	// Get agent for logging context
   783→	ag, err := GetCurrentHookAgent()
   784→	if err != nil {
   785→		return fmt.Errorf("failed to get agent: %w", err)
   786→	}
   787→
   788→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   789→	logging.Info(logCtx, "pre-task",
   790→		slog.String("hook", "pre-task"),
   791→		slog.String("hook_type", "subagent"),
   792→		slog.String("model_session_id", input.SessionID),
   793→		slog.String("transcript_path", input.TranscriptPath),
   794→		slog.String("tool_use_id", input.ToolUseID),
   795→	)
   796→
   797→	// Log context to stdout
   798→	logPreTaskHookContext(os.Stdout, input)
   799→
   800→	// Capture pre-task state locally (for computing new files when task completes).
   801→	// We don't create a shadow branch commit here. Commits are created during
   802→	// task completion (handleClaudeCodePostTask/handleClaudeCodePostTodo) only if the task resulted
   803→	// in file changes.
   804→	if err := CapturePreTaskState(input.ToolUseID); err != nil {
   805→		return fmt.Errorf("failed to capture pre-task state: %w", err)
   806→	}
   807→
   808→	return nil
   809→}
