   197→// ComputeNewFiles compares current untracked files with pre-prompt state
   198→// to find files that were created during the session.
   199→func ComputeNewFiles(preState *PrePromptState) ([]string, error) {
   200→	if preState == nil {
   201→		return nil, nil
   202→	}
