func TestCalculateTotalTokenUsage_SingleParse(t *testing.T) {
	// This test verifies that CalculateTotalTokenUsage parses the transcript
	// only once, not twice. We verify this by checking that the function
	// correctly extracts both token usage AND spawned agent IDs.

	tmpDir := t.TempDir()
	transcriptPath := tmpDir + "/transcript.jsonl"
	subagentsDir := tmpDir + "/subagents"

	// Create subagent directory
