		t.Fatal(err)
	}

	// Create main transcript with a Task tool result containing agent ID
	transcriptContent := []byte(
		`{"type":"user","uuid":"u1","message":{"content":"do something"}}` + "\n" +
		`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
		`{"type":"user","uuid":"u2","message":{"content":[{"type":"tool_result","tool_use_id":"task1","content":[{"type":"text","text":"Done\n\nagentId: subagent1"}]}]}}` + "\n",
	)
	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
		t.Fatal(err)
	}

	// Create subagent transcript
	subagentContent := []byte(
		`{"type":"assistant","uuid":"sa1","message":{"id":"sm1","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n",
	)
	if err := os.WriteFile(subagentsDir+"/agent-subagent1.jsonl", subagentContent, 0o600); err != nil {
		t.Fatal(err)
