	usage, err := CalculateTotalTokenUsage(transcriptPath, 0, subagentsDir)
	if err != nil {
		t.Fatalf("CalculateTotalTokenUsage error: %v", err)
	}

	// Verify main transcript tokens
	if usage.InputTokens != 100 || usage.OutputTokens != 50 {
		t.Errorf("Main tokens: got input=%d output=%d, want input=100 output=50",
			usage.InputTokens, usage.OutputTokens)
	}

	// Verify subagent tokens were found (proves agent IDs were extracted)
	if usage.SubagentTokens == nil {
		t.Fatal("SubagentTokens should not be nil - agent ID extraction failed")
	}
	if usage.SubagentTokens.InputTokens != 200 || usage.SubagentTokens.OutputTokens != 100 {
		t.Errorf("Subagent tokens: got input=%d output=%d, want input=200 output=100",
