func CalculateTotalTokenUsage(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
    // First parse via CalculateTokenUsageFromFile
    mainUsage, err := CalculateTokenUsageFromFile(transcriptPath, startLine)  // calls parseTranscriptFromLine internally
    if err != nil {
        return nil, fmt.Errorf("failed to calculate main token usage: %w", err)
    }

    // Second parse - redundant!
    transcript, err := parseTranscriptFromLine(transcriptPath, startLine)
    if err != nil {
        return nil, fmt.Errorf("failed to parse transcript for agent IDs: %w", err)
    }

    agentIDs := ExtractSpawnedAgentIDs(transcript)
    // ...
}
```

**After (single parsing):**
```go
func CalculateTotalTokenUsage(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
    if transcriptPath == "" {
        return &agent.TokenUsage{}, nil
    }

    // Parse transcript ONCE
    transcript, err := parseTranscriptFromLine(transcriptPath, startLine)
    if err != nil {
        return nil, fmt.Errorf("failed to parse transcript: %w", err)
    }

    // Calculate token usage from parsed transcript
    mainUsage := CalculateTokenUsage(transcript)

    // Extract spawned agent IDs from the same parsed transcript
    agentIDs := ExtractSpawnedAgentIDs(transcript)
    // ...
}
```

**Key changes:**
1. Added early return for empty `transcriptPath` (same behavior as `CalculateTokenUsageFromFile` had)
2. Parse transcript once using `parseTranscriptFromLine`
3. Call `CalculateTokenUsage` (not `CalculateTokenUsageFromFile`) on the parsed result
4. Call `ExtractSpawnedAgentIDs` on the same parsed result

**Tests:** All tests pass (`mise run test:ci`)
**Lint:** No issues (`mise run lint`)

