   154→			name: "files in sibling directories with repo root base",
   155→			files: []string{
   156→				"/repo/api/src/lib/github.ts",
   157→				"/repo/api/src/types.ts",
   158→				"/repo/frontend/src/pages/api.ts",
   159→			},
   160→			basePath: "/repo", // repo root
   161→			want: []string{
   162→				"api/src/lib/github.ts",
   163→				"api/src/types.ts",
   164→				"frontend/src/pages/api.ts",
   165→			},
   166→		},
   167→		{
