   170→				"/repo/api/src/lib/github.ts",
   171→				"/repo/frontend/src/pages/api.ts",
   172→			},
   173→			basePath: "/repo/frontend", // cwd in subdirectory
   174→			want: []string{
   175→				// Only frontend file should remain, api file gets filtered
   176→				// because ../api/... starts with ..
   177→				"src/pages/api.ts",
   178→			},
   179→		},
   180→		{
   181→			name: "relative paths pass through unchanged",
   182→			files: []string{
   183→				"src/file.ts",
   184→				"lib/util.go",
   185→			},
   186→			basePath: "/repo",
   187→			want: []string{
   188→				"src/file.ts",
   189→				"lib/util.go",
   190→			},
   191→		},
   192→		{
