		if st.Staging == git.Modified || st.Staging == git.Added {
			seen[file] = struct{}{}
		}
	}

	// Convert set to slice
	files := make([]string, 0, len(seen))
	for file := range seen {
		files = append(files, file)
	}

	return files, nil
