// handleLogsOnlyCheckout restores logs and checks out the commit (detached HEAD).
func handleLogsOnlyCheckout(start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
	// Resolve agent once for use throughout
	agent, err := getAgent(point.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	ctx := logging.WithComponent(context.Background(), "rewind")
	ctx = logging.WithAgent(ctx, agent.Name())

	logging.Debug(ctx, "logs-only checkout started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	// First, restore the logs
	restorer, ok := start.(strategy.LogsOnlyRestorer)
	if !ok {
		return errors.New("strategy does not support logs-only restoration")
	}

	if err := restorer.RestoreLogsOnly(point, true); err != nil { // force=true for explicit rewind
		logging.Error(ctx, "logs-only checkout failed during log restoration",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	// Show warning about detached HEAD
	var confirm bool
	confirmForm := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Create detached HEAD?").
				Description("This will checkout the commit directly. You'll be in 'detached HEAD' state.\nAny uncommitted changes will be lost!").
				Value(&confirm),
		),
	)

	if err := confirmForm.Run(); err != nil {
		return fmt.Errorf("confirmation cancelled: %w", err)
	}

	if !confirm {
		fmt.Println("Checkout cancelled. Session logs were still restored.")
		printMultiSessionResumeCommands(point, agent)
		return nil
	}

	// Perform git checkout
	if err := CheckoutBranch(point.ID); err != nil {
		logging.Error(ctx, "logs-only checkout failed during git checkout",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to checkout commit: %w", err)
	}

	logging.Debug(ctx, "logs-only checkout completed",
		slog.String("checkpoint_id", point.ID),
	)

	fmt.Printf("Checked out %s (detached HEAD).\n", shortID)
	printMultiSessionResumeCommands(point, agent)
	return nil
}

// handleLogsOnlyReset restores logs and resets the branch to the commit (destructive).
func handleLogsOnlyReset(start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
	// Resolve agent once for use throughout
	agent, agentErr := getAgent(point.Agent)
	if agentErr != nil {
		return fmt.Errorf("failed to get agent: %w", agentErr)
	}

	// Initialize logging context with agent from checkpoint
	ctx := logging.WithComponent(context.Background(), "rewind")
	ctx = logging.WithAgent(ctx, agent.Name())

	logging.Debug(ctx, "logs-only reset (interactive) started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	// First, restore the logs
	restorer, ok := start.(strategy.LogsOnlyRestorer)
	if !ok {
		return errors.New("strategy does not support logs-only restoration")
	}

	if err := restorer.RestoreLogsOnly(point, true); err != nil { // force=true for explicit rewind
		logging.Error(ctx, "logs-only reset failed during log restoration",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	// Get current HEAD before reset (for recovery message)
	currentHead, err := getCurrentHeadHash()
	if err != nil {
		// Non-fatal - just won't show recovery message
		currentHead = ""
	}

	// Get detailed uncommitted changes warning from strategy
	var uncommittedWarning string
	if _, warn, err := start.CanRewind(); err == nil {
		uncommittedWarning = warn
	}

	// Check for safety issues
	warnings, err := checkResetSafety(point.ID, uncommittedWarning)
	if err != nil {
		return fmt.Errorf("failed to check reset safety: %w", err)
	}

	// Build confirmation message based on warnings
	var confirmTitle, confirmDesc string
	if len(warnings) > 0 {
		confirmTitle = "⚠️  Reset branch with warnings?"
		confirmDesc = "WARNING - the following issues were detected:\n" +
			strings.Join(warnings, "\n") +
			"\n\nThis will move your branch to " + shortID + " and DISCARD commits after it!"
	} else {
		confirmTitle = "Reset branch to " + shortID + "?"
		confirmDesc = "This will move your branch pointer to this commit.\nCommits after this point will be orphaned (but recoverable via reflog)."
	}

	var confirm bool
	confirmForm := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(confirmTitle).
				Description(confirmDesc).
				Value(&confirm),
		),
	)

	if err := confirmForm.Run(); err != nil {
		return fmt.Errorf("confirmation cancelled: %w", err)
	}

	if !confirm {
		fmt.Println("Reset cancelled. Session logs were still restored.")
		printMultiSessionResumeCommands(point, agent)
		return nil
	}

	// Perform git reset --hard
	if err := gitutil.HardReset(point.ID); err != nil {
		logging.Error(ctx, "logs-only reset failed during git reset",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to reset branch: %w", err)
	}

	logging.Debug(ctx, "logs-only reset (interactive) completed",
		slog.String("checkpoint_id", point.ID),
	)

	fmt.Printf("Reset branch to %s.\n", shortID)
	printMultiSessionResumeCommands(point, agent)

	// Show recovery instructions
	if currentHead != "" && currentHead != point.ID {
		currentShort := currentHead
		if len(currentShort) > 7 {
			currentShort = currentShort[:7]
		}
		fmt.Printf("\nTo undo this reset: git reset --hard %s\n", currentShort)
	}

	return nil
}

// getCurrentHeadHash returns the current HEAD commit hash.
func getCurrentHeadHash() (string, error) {
	repo, err := openRepository()
	if err != nil {
		return "", err
	}

	head, err := repo.Head()
	if err != nil {
		return "", fmt.Errorf("failed to get HEAD: %w", err)
	}

	return head.Hash().String(), nil
}

// checkResetSafety checks for potential issues before a git reset --hard.
// Returns a list of warning messages (empty if safe to proceed without warnings).
// If uncommittedChangesWarning is provided, it will be used instead of a generic warning.
func checkResetSafety(targetCommitHash string, uncommittedChangesWarning string) ([]string, error) {
	var warnings []string

	repo, err := openRepository()
	if err != nil {
		return nil, err
	}

	// Check for uncommitted changes
	if uncommittedChangesWarning != "" {
		// Use the detailed warning from strategy's CanRewind()
		warnings = append(warnings, uncommittedChangesWarning)
	} else {
		// Fall back to generic check
		worktree, err := repo.Worktree()
		if err != nil {
			return nil, fmt.Errorf("failed to get worktree: %w", err)
		}

		status, err := worktree.Status()
		if err != nil {
			return nil, fmt.Errorf("failed to get status: %w", err)
		}

		if !status.IsClean() {
			warnings = append(warnings, "• You have uncommitted changes that will be LOST")
		}
	}

	// Check if current HEAD is ahead of target (we'd be discarding commits)
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	targetHash := plumbing.NewHash(targetCommitHash)

	// Count commits between target and HEAD
	commitsAhead, err := countCommitsBetween(repo, targetHash, head.Hash())
	if err != nil {
		// Non-fatal - just can't show commit count
		commitsAhead = -1
	}

	if commitsAhead > 0 {
		warnings = append(warnings, fmt.Sprintf("• %d commit(s) after this point will be orphaned", commitsAhead))
	}

	return warnings, nil
}

// countCommitsBetween counts commits between ancestor and descendant.
// Returns 0 if ancestor == descendant, -1 on error.
func countCommitsBetween(repo *git.Repository, ancestor, descendant plumbing.Hash) (int, error) {
	if ancestor == descendant {
		return 0, nil
	}

	// Walk from descendant back to ancestor
	count := 0
	current := descendant

	for count < 1000 { // Safety limit
		if current == ancestor {
			return count, nil
		}

		commit, err := repo.CommitObject(current)
		if err != nil {
			return -1, fmt.Errorf("failed to get commit: %w", err)
		}

		if commit.NumParents() == 0 {
			// Reached root without finding ancestor - ancestor not in history
			return -1, nil
		}

		count++
		current = commit.ParentHashes[0] // Follow first parent
	}

	return -1, nil
}

// performGitResetHard performs a git reset --hard to the specified commit.
// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
// deletes untracked directories (like .entire/) even when they're in .gitignore.
func performGitResetHard(commitHash string) error {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", commitHash)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
	}
	return nil
}

// sanitizeForTerminal removes or replaces characters that cause rendering issues
// in terminal UI components. This includes emojis with skin-tone modifiers and
// other multi-codepoint characters that confuse width calculations.
func sanitizeForTerminal(s string) string {
	var result strings.Builder
	result.Grow(len(s))

	for _, r := range s {
		// Skip emoji skin tone modifiers (U+1F3FB to U+1F3FF)
		if r >= 0x1F3FB && r <= 0x1F3FF {
			continue
		}
		// Skip zero-width joiners used in emoji sequences
		if r == 0x200D {
			continue
		}
		// Skip variation selectors (U+FE00 to U+FE0F)
		if r >= 0xFE00 && r <= 0xFE0F {
			continue
		}
		// Keep printable characters and common whitespace
		if unicode.IsPrint(r) || r == '\t' || r == '\n' {
			result.WriteRune(r)
		}
	}

	return result.String()
}

// formatResumeCommand returns the agent-appropriate command to resume a session.
func formatResumeCommand(entireSessionID string, agent agentpkg.Agent) string {
	agentSessionID := agent.ExtractAgentSessionID(entireSessionID)
	return agent.FormatResumeCommand(agentSessionID)
}

// printMultiSessionResumeCommands prints resume commands for all sessions in a rewind point.
// For single-session checkpoints, prints a single resume command.
// For multi-session checkpoints, prints all sessions with prompts as comments.
func printMultiSessionResumeCommands(point strategy.RewindPoint, agent agentpkg.Agent) {
	// Check if this is a multi-session checkpoint
	if point.SessionCount > 1 && len(point.SessionIDs) > 1 {
		fmt.Printf("\nRestored %d sessions. Resume with:\n", point.SessionCount)

		// Print each session with prompt as comment
		for i, sessionID := range point.SessionIDs {
			cmd := formatResumeCommand(sessionID, agent)

			// Get prompt for this session (if available)
			var prompt string
			if i < len(point.SessionPrompts) {
				prompt = point.SessionPrompts[i]
			}

			// Add "(most recent)" label to the last session
			if i == len(point.SessionIDs)-1 {
				if prompt != "" {
					fmt.Printf("  %s  # %s (most recent)\n", cmd, prompt)
				} else {
					fmt.Printf("  %s  # (most recent)\n", cmd)
				}
			} else {
				if prompt != "" {
					fmt.Printf("  %s  # %s\n", cmd, prompt)
				} else {
					fmt.Printf("  %s\n", cmd)
				}
			}
		}
	} else {
		// Single session - use traditional format with prompt if available
		sessionID := point.SessionID
		if sessionID == "" && len(point.SessionIDs) > 0 {
			sessionID = point.SessionIDs[len(point.SessionIDs)-1]
		}
		if sessionID != "" {
			cmd := formatResumeCommand(sessionID, agent)
			if point.SessionPrompt != "" {
				fmt.Printf("%s  # %s\n", cmd, point.SessionPrompt)
			} else {
				fmt.Printf("%s\n", cmd)
			}
		}
	}
}

package strategy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// pushSessionsBranchCommon is the shared implementation for pushing session branches.
// Used by both manual-commit and auto-commit strategies.
// By default, session logs are pushed automatically alongside user pushes.
// Configuration (stored in .entire/settings.json under strategy_options.push_sessions):
//   - false: disable automatic pushing
//   - true or not set: push automatically (default)
func pushSessionsBranchCommon(remote, branchName string) error {
	// Check if pushing is disabled
	if isPushSessionsDisabled() {
		return nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if branch exists locally
	branchRef := plumbing.NewBranchReferenceName(branchName)
	localRef, err := repo.Reference(branchRef, true)
	if err != nil {
		// No branch, nothing to push
		return nil //nolint:nilerr // Expected when no sessions exist yet
	}

	// Check if there's actually something to push (local differs from remote)
	if !hasUnpushedSessionsCommon(repo, remote, localRef.Hash(), branchName) {
		// Nothing to push - skip silently
		return nil
	}

	return doPushSessionsBranch(remote, branchName)
}

// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remote>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

// isPushSessionsDisabled checks if push_sessions is disabled in settings.
// Returns true if push_sessions is explicitly set to false.
// Checks settings.local.json first (user preference), then settings.json (shared).
func isPushSessionsDisabled() bool {
	// Use repo root to find settings files when run from a subdirectory
	localSettingsPath, err := paths.AbsPath(".entire/settings.local.json")
	if err != nil {
		localSettingsPath = ".entire/settings.local.json" // Fallback
	}
	sharedSettingsPath, err := paths.AbsPath(".entire/settings.json")
	if err != nil {
		sharedSettingsPath = ".entire/settings.json" // Fallback
	}

	// Try local settings first (user preference, not committed)
	if disabled, found := readPushSessionsFromFile(localSettingsPath); found {
		return disabled
	}

	// Fall back to shared settings
	if disabled, found := readPushSessionsFromFile(sharedSettingsPath); found {
		return disabled
	}

	// Default: push is enabled
	return false
}

// readPushSessionsFromFile reads push_sessions from a specific settings file.
// Returns (isDisabled, found). If not found, returns (false, false).
func readPushSessionsFromFile(settingsPath string) (bool, bool) {
	//nolint:gosec // G304: settingsPath is always a hardcoded constant from this package
	data, err := os.ReadFile(settingsPath)
	if err != nil {
		return false, false
	}

	var settings struct {
		StrategyOptions map[string]interface{} `json:"strategy_options"`
	}
	if err := json.Unmarshal(data, &settings); err != nil {
		return false, false
	}

	if settings.StrategyOptions == nil {
		return false, false
	}

	val, exists := settings.StrategyOptions["push_sessions"]
	if !exists {
		return false, false
	}

	// Handle boolean value
	if boolVal, ok := val.(bool); ok {
		return !boolVal, true // disabled = !push_sessions
	}

	return false, false
}

// doPushSessionsBranch pushes the sessions branch to the remote.
func doPushSessionsBranch(remote, branchName string) error {
	fmt.Fprintf(os.Stderr, "[entire] Pushing session logs to %s...\n", remote)

	// Try pushing first
	if err := tryPushSessionsCommon(remote, branchName); err == nil {
		return nil
	}

	// Push failed - likely non-fast-forward. Try to fetch and merge.
	fmt.Fprintf(os.Stderr, "[entire] Syncing with remote session logs...\n")

	if err := fetchAndMergeSessionsCommon(remote, branchName); err != nil {
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync sessions: %v\n", err)
		return nil // Don't fail the main push
	}

	// Try pushing again after merge
	if err := tryPushSessionsCommon(remote, branchName); err != nil {
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push sessions after sync: %v\n", err)
	}

	return nil
}

// tryPushSessionsCommon attempts to push the sessions branch.
func tryPushSessionsCommon(remote, branchName string) error {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()

	// Use --no-verify to prevent recursive hook calls
	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", remote, branchName)
	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context

	output, err := cmd.CombinedOutput()
	if err != nil {
		// Check if it's a non-fast-forward error (we can try to recover)
		if strings.Contains(string(output), "non-fast-forward") ||
			strings.Contains(string(output), "rejected") {
			return errors.New("non-fast-forward")
		}
		return fmt.Errorf("push failed: %s", output)
	}
	return nil
}

// fetchAndMergeSessionsCommon fetches remote sessions and merges into local using go-git.
// Since session logs are append-only (unique cond-* directories), we just combine trees.
func fetchAndMergeSessionsCommon(remote, branchName string) error {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()

	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
	fetchCmd := exec.CommandContext(ctx, "git", "fetch", remote, branchName)
	fetchCmd.Stdin = nil
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("fetch failed: %s", output)
	}

	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get local branch
	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	// Get remote (FETCH_HEAD)
	fetchHeadRef, err := repo.Reference(plumbing.ReferenceName("FETCH_HEAD"), true)
	if err != nil {
		return fmt.Errorf("failed to get FETCH_HEAD: %w", err)
	}
	remoteCommit, err := repo.CommitObject(fetchHeadRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get remote commit: %w", err)
	}
	remoteTree, err := remoteCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get remote tree: %w", err)
	}

	// Flatten both trees and combine entries
	// Session logs have unique cond-* directories, so no conflicts expected
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten remote tree: %w", err)
	}

	// Build merged tree
	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	// Create merge commit with both parents
	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{localRef.Hash(), fetchHeadRef.Hash()},
		"Merge remote session logs")
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), mergeCommitHash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch ref: %w", err)
	}

	return nil
}

// createMergeCommitCommon creates a merge commit with multiple parents.
func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       sig,
		Committer:    sig,
		Message:      message,
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

