    57→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
    58→// Returns (isDefault, branchName, error)
    59→func IsOnDefaultBranch() (bool, string, error) {
    60→	repo, err := gitutil.OpenRepository()
    61→	if err != nil {
    62→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
    63→	}
