    66→	head, err := repo.Head()
    67→	if err != nil {
    68→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
    69→	}
    70→
    71→	if !head.Name().IsBranch() {
    72→		// Detached HEAD - not on any branch
    73→		return false, "", nil
    74→	}
    75→
    76→	currentBranch := head.Name().Short()
    77→
    78→	// Try to get default branch from remote origin's HEAD
    79→	defaultBranch := getDefaultBranchFromRemote(repo)
    80→
