    84→		if currentBranch == "main" || currentBranch == "master" {
    85→			return true, currentBranch, nil
    86→		}
    87→		return false, currentBranch, nil
    88→	}
    89→
    90→	return currentBranch == defaultBranch, currentBranch, nil
