			existingSessionID[4] == '-' &&
			existingSessionID[7] == '-' &&
			existingSessionID[10] == '-' {
			// Extract the agent ID portion and compare
			extractedAgentID := existingSessionID[11:]
			if extractedAgentID == agentSessionID {
				return existingSessionID
			}
		}
	}

	return ""
}

