		exists, err := gitutil.BranchExistsOnRemote("nonexistent")
		if err != nil {
			t.Fatalf("gitutil.BranchExistsOnRemote() error = %v", err)
		}
		if exists {
			t.Error("gitutil.BranchExistsOnRemote() = true, want false for nonexistent remote branch")
		}
	})
}

