   234→func TestHasUncommittedChanges(t *testing.T) {
   235→	// Create temp directory for test repo
   236→	tmpDir := t.TempDir()
   237→	t.Chdir(tmpDir)
   238→
   239→	// Initialize repo
   240→	repo, err := git.PlainInit(tmpDir, false)
   241→	if err != nil {
   242→		t.Fatalf("Failed to init repo: %v", err)
   243→	}
