   245→	w, err := repo.Worktree()
   246→	if err != nil {
   247→		t.Fatalf("Failed to get worktree: %v", err)
   248→	}
   249→
   250→	// Create initial commit
   251→	testFile := filepath.Join(tmpDir, "test.txt")
   252→	if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
   253→		t.Fatalf("Failed to write test file: %v", err)
