   258→	if _, err := w.Commit("initial commit", &git.CommitOptions{
   259→		Author: &object.Signature{
   260→			Name:  "Test",
   261→			Email: "test@example.com",
   262→		},
   263→	}); err != nil {
   264→		t.Fatalf("Failed to commit: %v", err)
   265→	}
   266→
   267→	// Test clean working tree
   268→	hasChanges, err := gitutil.HasUncommittedChanges()
   269→	if err != nil {
   270→		t.Fatalf("gitutil.HasUncommittedChanges() error = %v", err)
   271→	}
   272→	if hasChanges {
   273→		t.Error("gitutil.HasUncommittedChanges() = true, want false for clean tree")
   274→	}
   275→
   276→	// Make unstaged change
   277→	if err := os.WriteFile(testFile, []byte("modified"), 0o644); err != nil {
   278→		t.Fatalf("Failed to write test file: %v", err)
   279→	}
   280→
   281→	// Test with unstaged changes
   282→	hasChanges, err = gitutil.HasUncommittedChanges()
   283→	if err != nil {
   284→		t.Fatalf("gitutil.HasUncommittedChanges() error = %v", err)
   285→	}
   286→	if !hasChanges {
   287→		t.Error("gitutil.HasUncommittedChanges() = false, want true for modified file")
   288→	}
   289→
   290→	// Stage the change
   291→	if _, err := w.Add("test.txt"); err != nil {
   292→		t.Fatalf("Failed to add test file: %v", err)
   293→	}
   294→
   295→	// Test with staged changes
   296→	hasChanges, err = gitutil.HasUncommittedChanges()
   297→	if err != nil {
   298→		t.Fatalf("gitutil.HasUncommittedChanges() error = %v", err)
   299→	}
   300→	if !hasChanges {
   301→		t.Error("gitutil.HasUncommittedChanges() = false, want true for staged file")
   302→	}
   303→
   304→	// Commit and add untracked file
   305→	if _, err := w.Commit("second commit", &git.CommitOptions{
   306→		Author: &object.Signature{
   307→			Name:  "Test",
   308→			Email: "test@example.com",
   309→		},
   310→	}); err != nil {
   311→		t.Fatalf("Failed to commit: %v", err)
   312→	}
   313→	if err := os.WriteFile(filepath.Join(tmpDir, "untracked.txt"), []byte("new"), 0o644); err != nil {
   314→		t.Fatalf("Failed to write untracked file: %v", err)
   315→	}
   316→
   317→	// Test with untracked file (should be true)
   318→	hasChanges, err = gitutil.HasUncommittedChanges()
   319→	if err != nil {
   320→		t.Fatalf("gitutil.HasUncommittedChanges() error = %v", err)
   321→	}
