   331→	// Test global gitignore (core.excludesfile) handling
   332→	// go-git doesn't read global gitignore, so we use git CLI instead.
   333→	// Simulate global gitignore by setting core.excludesfile in repo config.
   334→	// The file must be outside the repo to avoid showing up as untracked itself.
   335→	globalIgnoreDir := t.TempDir()
   336→	globalIgnoreFile := filepath.Join(globalIgnoreDir, "global-gitignore")
   337→	if err := os.WriteFile(globalIgnoreFile, []byte("*.globally-ignored\n"), 0o644); err != nil {
