   348→	// Create a file that matches the global ignore pattern
   349→	if err := os.WriteFile(filepath.Join(tmpDir, "secret.globally-ignored"), []byte("ignored"), 0o644); err != nil {
   350→		t.Fatalf("Failed to write globally ignored file: %v", err)
   351→	}
   352→
   353→	// Test with globally gitignored file - should return false (clean)
   354→	// This catches regressions if someone switches back to go-git's Status()
   355→	// which doesn't read core.excludesfile (global gitignore)
   356→	hasChanges, err = gitutil.HasUncommittedChanges()
   357→	if err != nil {
   358→		t.Fatalf("gitutil.HasUncommittedChanges() error = %v", err)
   359→	}
   360→	if hasChanges {
