   387→			preExisting: []string{},
   388→			expected:    []string{"file1.go", "file2.go"},
   389→		},
   390→		{
   391→			name:        "returns nil when current is empty",
   392→			current:     []string{},
   393→			preExisting: []string{"file1.go"},
   394→			expected:    nil,
   395→		},
   396→		{
   397→			name:        "handles nil current slice",
   398→			current:     nil,
   399→			preExisting: []string{"file1.go"},
   400→			expected:    nil,
   401→		},
   402→		{
   403→			name:        "handles nil pre-existing slice",
   404→			current:     []string{"file1.go", "file2.go"},
   405→			preExisting: nil,
   406→			expected:    []string{"file1.go", "file2.go"},
   407→		},
   408→		{
   409→			name:        "handles both nil slices",
   410→			current:     nil,
