     1→// Package gitutil provides git repository utilities using native git CLI commands.
     2→// This package exists because go-git has known issues with certain operations:
     3→//   - worktree.Status() doesn't respect global gitignore (core.excludesfile)
     4→//   - worktree.Reset() with HardReset deletes ignored directories
     5→//   - worktree.Checkout() has similar issues with untracked files
     6→//
     7→// By using native git commands, we ensure full compatibility with git's behavior.
     8→// See: https://github.com/entireio/cli/pull/129
     9→package gitutil
    10→
    11→import (
    12→	"context"
    13→	"errors"
    14→	"fmt"
    15→	"os"
    16→	"os/exec"
    17→	"path/filepath"
    18→	"strings"
    19→
    20→	"github.com/go-git/go-git/v5"
    21→	"github.com/go-git/go-git/v5/config"
    22→	"github.com/go-git/go-git/v5/plumbing"
    23→)
    24→
    25→// Common directory names
    26→const (
    27→	GitDir = ".git"
    28→)
    29→
    30→// OpenRepository opens the git repository with linked worktree support enabled.
    31→// Uses 'git rev-parse --show-toplevel' to find the repository root, which works
    32→// correctly even when called from a subdirectory within the repo.
    33→//
    34→// This is the canonical way to open a repository in this codebase. It handles:
    35→//   - Subdirectory execution (finds repo root automatically)
    36→//   - Linked worktrees (enables EnableDotGitCommonDir)
    37→func OpenRepository() (*git.Repository, error) {
    38→	// Find the repository root using git rev-parse --show-toplevel
    39→	// This works correctly from any subdirectory within the repository
    40→	repoRoot, err := GetWorktreePath()
    41→	if err != nil {
    42→		// Fallback to current directory if git command fails
    43→		// (e.g., if git is not installed or we're not in a repo)
    44→		repoRoot = "."
    45→	}
    46→
    47→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
    48→		EnableDotGitCommonDir: true,
    49→	})
    50→	if err != nil {
    51→		return nil, fmt.Errorf("failed to open repository: %w", err)
    52→	}
    53→	return repo, nil
    54→}
    55→
    56→// GetWorktreePath returns the absolute path to the current worktree root.
    57→// This is the working directory path, not the git directory.
    58→// Works correctly from any subdirectory within the repository.
    59→func GetWorktreePath() (string, error) {
    60→	ctx := context.Background()
    61→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
    62→	output, err := cmd.Output()
    63→	if err != nil {
    64→		return "", fmt.Errorf("failed to get worktree path: %w", err)
    65→	}
    66→	return strings.TrimSpace(string(output)), nil
    67→}
    68→
    69→// IsInsideWorktree returns true if the current directory is inside a git worktree
    70→// (as opposed to the main repository). Worktrees have .git as a file pointing
    71→// to the main repo, while the main repo has .git as a directory.
    72→// This function works correctly from any subdirectory within the repository.
    73→func IsInsideWorktree() bool {
    74→	// First find the repository root
    75→	repoRoot, err := GetWorktreePath()
    76→	if err != nil {
    77→		return false
    78→	}
    79→
    80→	gitPath := filepath.Join(repoRoot, GitDir)
    81→	gitInfo, err := os.Stat(gitPath)
    82→	if err != nil {
    83→		return false
    84→	}
    85→	return !gitInfo.IsDir()
    86→}
    87→
    88→// GetMainRepoRoot returns the root directory of the main repository.
    89→// In the main repo, this is the worktree path (repo root).
    90→// In a worktree, this parses the .git file to find the main repo.
    91→// This function works correctly from any subdirectory within the repository.
    92→//
    93→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
    94→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
    95→// See: https://git-scm.com/docs/gitrepository-layout
    96→func GetMainRepoRoot() (string, error) {
    97→	// First find the worktree/repo root
    98→	repoRoot, err := GetWorktreePath()
    99→	if err != nil {
   100→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   101→	}
   102→
   103→	if !IsInsideWorktree() {
   104→		return repoRoot, nil
   105→	}
   106→
   107→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
   108→	gitFilePath := filepath.Join(repoRoot, GitDir)
   109→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
   110→	if err != nil {
   111→		return "", fmt.Errorf("failed to read .git file: %w", err)
   112→	}
   113→
   114→	gitdir := strings.TrimSpace(string(content))
   115→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
   116→
   117→	// Extract main repo root: everything before "/.git/"
   118→	idx := strings.LastIndex(gitdir, "/.git/")
   119→	if idx < 0 {
   120→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
   121→	}
   122→	return gitdir[:idx], nil
   123→}
   124→
   125→// GetGitCommonDir returns the path to the shared git directory.
   126→// In a regular checkout, this is .git/
   127→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   128→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
   129→func GetGitCommonDir() (string, error) {
   130→	ctx := context.Background()
   131→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   132→	cmd.Dir = "."
   133→	output, err := cmd.Output()
   134→	if err != nil {
   135→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   136→	}
   137→
   138→	commonDir := strings.TrimSpace(string(output))
   139→
   140→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   141→	// so we need to make it absolute if it isn't already
   142→	if !filepath.IsAbs(commonDir) {
   143→		commonDir = filepath.Join(".", commonDir)
   144→	}
   145→
   146→	return filepath.Clean(commonDir), nil
   147→}
   148→
   149→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   150→// It checks local config first, then falls back to global config.
   151→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
   152→// operations to proceed even without git user config, which is especially useful
   153→// for internal metadata commits on branches like entire/sessions.
   154→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   155→	// Get repository config (includes local settings)
   156→	cfg, err := repo.Config()
   157→	if err == nil {
   158→		name = cfg.User.Name
   159→		email = cfg.User.Email
   160→	}
   161→
   162→	// If not found in local config, try global config
   163→	if name == "" || email == "" {
   164→		globalCfg, err := config.LoadConfig(config.GlobalScope)
   165→		if err == nil {
   166→			if name == "" {
   167→				name = globalCfg.User.Name
   168→			}
   169→			if email == "" {
   170→				email = globalCfg.User.Email
   171→			}
   172→		}
   173→	}
   174→
   175→	// Provide sensible defaults if git user is not configured
   176→	if name == "" {
   177→		name = "Unknown"
   178→	}
   179→	if email == "" {
   180→		email = "unknown@local"
   181→	}
   182→
   183→	return name, email
   184→}
   185→
   186→// GitAuthor represents the git user configuration
   187→type GitAuthor struct {
   188→	Name  string
   189→	Email string
   190→}
   191→
   192→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
   193→// It checks local config first, then falls back to global config.
   194→// If go-git can't find the config, it falls back to using the git command.
   195→// Returns fallback defaults if no user is configured anywhere.
   196→func GetGitAuthor() (*GitAuthor, error) {
   197→	repo, err := OpenRepository()
   198→	if err != nil {
   199→		return nil, fmt.Errorf("failed to open git repository: %w", err)
   200→	}
   201→
   202→	name, email := GetGitAuthorFromRepo(repo)
   203→
   204→	// If go-git returned defaults, try using git command as fallback
   205→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
   206→	// non-standard config locations, or environment issues in hook contexts)
   207→	if name == "Unknown" {
   208→		if gitName := GetConfigValue("user.name"); gitName != "" {
   209→			name = gitName
   210→		}
   211→	}
   212→	if email == "unknown@local" {
   213→		if gitEmail := GetConfigValue("user.email"); gitEmail != "" {
   214→			email = gitEmail
   215→		}
   216→	}
   217→
   218→	return &GitAuthor{
   219→		Name:  name,
   220→		Email: email,
   221→	}, nil
   222→}
   223→
   224→// IsOnDefaultBranch checks if the repository is currently on the default branch.
   225→// It determines the default branch by:
   226→// 1. Checking the remote origin's HEAD reference
   227→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
   228→// Returns (isDefault, branchName, error)
   229→func IsOnDefaultBranch() (bool, string, error) {
   230→	repo, err := OpenRepository()
   231→	if err != nil {
   232→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
   233→	}
   234→
   235→	// Get current branch
   236→	head, err := repo.Head()
   237→	if err != nil {
   238→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
   239→	}
   240→
   241→	if !head.Name().IsBranch() {
   242→		// Detached HEAD - not on any branch
   243→		return false, "", nil
   244→	}
   245→
   246→	currentBranch := head.Name().Short()
   247→
   248→	// Try to get default branch from remote origin's HEAD
   249→	defaultBranch := GetDefaultBranchFromRemote(repo)
   250→
   251→	// If we couldn't determine from remote, use common defaults
   252→	if defaultBranch == "" {
   253→		// Check if current branch is a common default name
   254→		if currentBranch == "main" || currentBranch == "master" {
   255→			return true, currentBranch, nil
   256→		}
   257→		return false, currentBranch, nil
   258→	}
   259→
   260→	return currentBranch == defaultBranch, currentBranch, nil
   261→}
   262→
   263→// GetDefaultBranchFromRemote tries to determine the default branch from the origin remote.
   264→// Returns empty string if unable to determine.
   265→func GetDefaultBranchFromRemote(repo *git.Repository) string {
   266→	// Try to get the symbolic reference for origin/HEAD
   267→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
   268→	if err == nil && ref != nil {
   269→		// ref.Target() gives us something like "refs/remotes/origin/main"
   270→		target := ref.Target().String()
   271→		if after, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
   272→			return after
   273→		}
   274→	}
   275→
   276→	// Fallback: check if origin/main or origin/master exists
   277→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
   278→		return "main"
   279→	}
   280→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
   281→		return "master"
   282→	}
   283→
   284→	return ""
   285→}
   286→
   287→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
   288→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
   289→// skip the operation to avoid polluting main/master history.
   290→// If the branch cannot be determined, returns (false, "") to allow the operation.
   291→func ShouldSkipOnDefaultBranch() (bool, string) {
   292→	isDefault, branchName, err := IsOnDefaultBranch()
   293→	if err != nil {
   294→		// If we can't determine, allow the operation
   295→		return false, ""
   296→	}
   297→	return isDefault, branchName
   298→}
   299→
   300→// ShouldSkipOnDefaultBranchForStrategy checks if we're on the default branch and
   301→// whether the strategy allows operating on it.
   302→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
   303→// skip the operation. Strategies that allow main branch return false.
   304→func ShouldSkipOnDefaultBranchForStrategy(allowsMainBranch bool) (bool, string) {
   305→	isDefault, branchName, err := IsOnDefaultBranch()
   306→	if err != nil {
   307→		// If we can't determine, allow the operation
   308→		return false, ""
   309→	}
   310→	if !isDefault {
   311→		return false, branchName
   312→	}
   313→
   314→	if allowsMainBranch {
   315→		return false, branchName
   316→	}
   317→
   318→	return true, branchName
   319→}
   320→
   321→// GetCurrentBranch returns the name of the current branch.
   322→// Returns an error if in detached HEAD state or if not in a git repository.
   323→func GetCurrentBranch() (string, error) {
   324→	repo, err := OpenRepository()
   325→	if err != nil {
   326→		return "", fmt.Errorf("failed to open git repository: %w", err)
   327→	}
   328→
   329→	head, err := repo.Head()
   330→	if err != nil {
   331→		return "", fmt.Errorf("failed to get HEAD: %w", err)
   332→	}
   333→
   334→	if !head.Name().IsBranch() {
   335→		return "", errors.New("not on a branch (detached HEAD)")
   336→	}
   337→
   338→	return head.Name().Short(), nil
   339→}
   340→
   341→// GetMergeBase finds the common ancestor (merge-base) between two branches.
   342→// Returns the hash of the merge-base commit.
   343→func GetMergeBase(branch1, branch2 string) (*plumbing.Hash, error) {
   344→	repo, err := OpenRepository()
   345→	if err != nil {
   346→		return nil, fmt.Errorf("failed to open git repository: %w", err)
   347→	}
   348→
   349→	// Resolve branch references
   350→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
   351→	if err != nil {
   352→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
   353→	}
   354→
   355→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
   356→	if err != nil {
   357→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
   358→	}
   359→
   360→	// Get commit objects
   361→	commit1, err := repo.CommitObject(ref1.Hash())
   362→	if err != nil {
   363→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
   364→	}
   365→
   366→	commit2, err := repo.CommitObject(ref2.Hash())
   367→	if err != nil {
   368→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
   369→	}
   370→
   371→	// Find common ancestor
   372→	mergeBase, err := commit1.MergeBase(commit2)
   373→	if err != nil {
   374→		return nil, fmt.Errorf("failed to find merge base: %w", err)
   375→	}
   376→
   377→	if len(mergeBase) == 0 {
   378→		return nil, errors.New("no common ancestor found")
   379→	}
   380→
   381→	hash := mergeBase[0].Hash
   382→	return &hash, nil
   383→}
   384→
   385→// BranchExistsOnRemote checks if a branch exists on the origin remote.
   386→// Returns true if the branch is tracked on origin, false otherwise.
   387→func BranchExistsOnRemote(branchName string) (bool, error) {
   388→	repo, err := OpenRepository()
   389→	if err != nil {
   390→		return false, fmt.Errorf("failed to open git repository: %w", err)
   391→	}
   392→
   393→	// Check for remote reference: refs/remotes/origin/<branchName>
   394→	_, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
   395→	if err != nil {
   396→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
   397→			return false, nil
   398→		}
   399→		return false, fmt.Errorf("failed to check remote branch: %w", err)
   400→	}
   401→
   402→	return true, nil
   403→}
   404→
   405→// BranchExistsLocally checks if a local branch exists.
   406→func BranchExistsLocally(branchName string) (bool, error) {
   407→	repo, err := OpenRepository()
   408→	if err != nil {
   409→		return false, fmt.Errorf("failed to open git repository: %w", err)
   410→	}
   411→
   412→	_, err = repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
   413→	if err != nil {
   414→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
   415→			return false, nil
   416→		}
   417→		return false, fmt.Errorf("failed to check branch: %w", err)
   418→	}
   419→
   420→	return true, nil
   421→}
