	globalIgnoreFile := filepath.Join(globalIgnoreDir, "global-gitignore")
	if err := os.WriteFile(globalIgnoreFile, []byte("*.globally-ignored\n"), 0o644); err != nil {
		t.Fatalf("Failed to write global gitignore: %v", err)
	}

