			Name:  "Test User",
			Email: "test@example.com",
		},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// Simulate session: delete tracked1.txt and create a new file
	if err := os.Remove(trackedFile1); err != nil {
